249	  const resetTimerRef = useRef<NodeJS.Timeout | null>(null);
250	  const processingTimerRef = useRef<NodeJS.Timeout | null>(null);
251	  const supabase = useMemo(() => createSupabaseBrowserClient(), []);
252	
253	  useEffect(() => {
254	    setKioskState('idle');
255	  }, []);
256	
257	  const resetToIdle = useCallback(() => {
258	    if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
259	    if (processingTimerRef.current) clearTimeout(processingTimerRef.current);
260	    setKioskState('idle');
261	    setInputValue('');
262	    setMessage('');
263	    setSubMessage('');
264	    setQrToken(null);
265	    setAttendanceType(null);
266	  }, []);
267	
268	  const handleFormSubmit = useCallback(async (submissionType: 'idle' | 'register', cardId: string) => {
269	    if (!cardId.trim()) {
270	      setInputValue('');
271	      return;
272	    }
273	
274	    setKioskState('processing');
275	    setInputValue('');
276	
277	    // Client-side timeout for processing state
278	    if (processingTimerRef.current) clearTimeout(processingTimerRef.current);
279	    processingTimerRef.current = setTimeout(() => {
280	      setKioskState('error');
281	      setMessage('応答がタイムアウトしました');
282	      setSubMessage('もう一度カードをタッチしてください');
283	    }, PROCESSING_TIMEOUT);
284	
285	    try {
286	        const result: any = await processSubmission(supabase, submissionType, cardId);
287	
288	        // Clear processing timeout since we got a response
289	        if (processingTimerRef.current) clearTimeout(processingTimerRef.current);
290	        
291	        if (submissionType === 'register') {
292	          if (result.success && result.token) {
293	            setQrToken(result.token);
294	            setQrExpiry(Date.now() + 30 * 60 * 1000);
295	            setKioskState('qr');
296	          } else {
297	            setKioskState('error');
298	            setMessage(result.message);
299	            setSubMessage('');
300	          }
301	        } else { // 'idle'
302	          if (result.success && result.user) {
303	            setKioskState('success');
304	            setAttendanceType(result.type);
305	            setMessage(`${result.user.display_name}`);
306	            setSubMessage(result.message);
307	          } else {
308	            setKioskState('error');
309	            setMessage(result.message);
310	            setSubMessage('登録するには「/」キーを押してください');
311	          }
312	        }
313	    } catch (error) {
314	        if (processingTimerRef.current) clearTimeout(processingTimerRef.current);
315	        console.error("Submission failed:", error);
316	        setKioskState('error');
317	        setMessage('サーバーとの通信に失敗しました。');
318	        setSubMessage('ネットワーク接続を確認して、もう一度お試しください。');
319	    }
320	  }, [supabase]);
321	
322	  useEffect(() => {
323	    if (kioskState === 'success' || kioskState === 'error') {
324	      if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
325	      resetTimerRef.current = setTimeout(resetToIdle, AUTO_RESET_DELAY);
326	    }
327	    return () => {
328	      if (resetTimerRef.current) clearTimeout(resetTimerRef.current);
329	    };
330	  }, [kioskState, resetToIdle]);
331	  
332	  useEffect(() => {
333	    const handleKeyDown = (e: KeyboardEvent) => {
334	      if (kioskState === 'loading' || (kioskState === 'qr' && e.key !== 'Escape')) {
335	        return;
336	      }
337	
338	      if (e.key === 'Escape') {
339	        resetToIdle();
340	        return;
341	      }
342	
343	      if (kioskState === 'processing') {
344	        return;
345	      }
346	      
347	      if (e.key === 'Enter') {
348	        const submissionType = kioskState === 'register' ? 'register' : 'idle';
349	        if (inputValue.trim()) {
350	            handleFormSubmit(submissionType, inputValue);
351	        }
352	        return;
353	      }
354	      
355	      if (e.key === '/') {
356	        e.preventDefault();
357	        setKioskState('register');
358	        setMessage('新規カード登録');
359	        setSubMessage('登録したいカードをタッチしてください');
360	        setInputValue('');
361	        return;
362	      }
363	      
364	      if (e.key.length === 1 && !e.ctrlKey && !e.metaKey) {
365	        setInputValue(prev => prev + e.key);
366	        if (kioskState === 'idle' || kioskState === 'success' || kioskState === 'error') {
367	           setKioskState('input');
368	        }
369	      }
370	
371	      if (e.key === 'Backspace') {
372	        setInputValue(prev => prev.slice(0, -1));
373	      }
374	    };
375	    
376	    window.addEventListener('keydown', handleKeyDown);
377	    return () => window.removeEventListener('keydown', handleKeyDown);
378	  }, [kioskState, inputValue, handleFormSubmit, resetToIdle]);
379	  
380	  useEffect(() => {
381	    const fetchWbgt = async () => {
382	      try {
383	        const response = await fetch('https://stem-weather.vercel.app/api/wbgt');
384	        if (!response.ok) {
385	          console.error('Failed to fetch WBGT data, status:', response.status);
386	          return;
387	        }
388	        const data = await response.json();
389	        if (data.wbgt !== undefined) {
390	          setWbgtData({ wbgt: data.wbgt, timestamp: data.timestamp });
391	        }
392	      } catch (error) {
393	        console.error('Error fetching WBGT data:', error);
394	      }
395	    };
396	
397	    fetchWbgt(); // Fetch on initial load
398	    const intervalId = setInterval(fetchWbgt, 30 * 60 * 1000); // Fetch every 30 minutes
399	
400	    return () => clearInterval(intervalId); // Cleanup on unmount
401	  }, []);
402	
403	  useEffect(() => {
404	    if (!qrToken) return;
405	
406	    const channel = supabase
407	      .channel(`kiosk-qr-channel-${qrToken}`)
408	      .on(
409	        'postgres_changes',
410	        { event: 'UPDATE', schema: 'attendance', table: 'temp_registrations', filter: `qr_token=eq.${qrToken}` },
411	        (payload) => {
412	          if ((payload.new.accessed_at || payload.new.is_used) && kioskState === 'qr') {
413	            resetToIdle();
414	          }
415	        }
416	      ).subscribe();
417	    
418	    return () => {
419	      supabase.removeChannel(channel);
420	    };
421	  }, [supabase, qrToken, resetToIdle, kioskState]);
422	  
423	  return (
424	    <div className="h-screen w-screen bg-gray-900 text-white flex items-center justify-center font-sans p-2">
425	      <div className="w-full h-full bg-gray-900 border-4 border-gray-700 rounded-lg shadow-2xl overflow-hidden">
426	        <div className="w-full h-full flex flex-col items-center justify-center">
427	          {kioskState === 'idle' && <IdleScreen wbgtData={wbgtData} />}
428	          {kioskState === 'success' && <SuccessScreen message={message} subMessage={subMessage} attendanceType={attendanceType} />}
429	          {kioskState === 'error' && <ErrorScreen message={message} subMessage={subMessage} />}
430	          {kioskState === 'register' && <RegisterScreen message={message} subMessage={subMessage} />}
431	          {kioskState === 'qr' && qrToken && <QrScreen qrToken={qrToken} qrExpiry={qrExpiry} onExpire={resetToIdle} />}
432	          {(kioskState === 'loading' || kioskState === 'processing') && <ProcessingScreen state={kioskState} />}
433	        </div>
434	        
435	        {(kioskState === 'input' || (kioskState === 'register' && inputValue)) && (
436	          <div className="absolute bottom-0 left-0 right-0 p-4 bg-black/50 backdrop-blur-sm">
437	            <div className="w-full max-w-4xl mx-auto text-center">
438	              <p className="text-lg text-gray-400 mb-2">読み取り中...</p>
439	              <p className="text-2xl font-mono bg-gray-800 px-4 py-2 rounded-lg inline-block">{inputValue}</p>
440	            </div>
441	          </div>
442	        )}
443	      </div>
444	    </div>
445	  );
446	}
