1	-- Add display_name column to member.members (cache for Discord nickname)
2	ALTER TABLE member.members ADD COLUMN IF NOT EXISTS display_name text;
3	
4	-- Create RPC function for single-call kiosk attendance recording
5	-- Called directly from browser (bypasses Vercel serverless for speed)
6	-- Falls back to auth.users global_name if display_name is NULL
7	CREATE OR REPLACE FUNCTION attendance.record_attendance_by_card(p_card_id text)
8	RETURNS json
9	LANGUAGE plpgsql
10	SECURITY DEFINER
11	SET search_path = attendance, member
12	AS $$
13	DECLARE
14	  v_user_id uuid;
15	  v_display_name text;
16	  v_discord_uid text;
17	  v_last_type text;
18	  v_new_type text;
19	  v_now timestamptz := now();
20	  v_date date := (v_now AT TIME ZONE 'Asia/Tokyo')::date;
21	BEGIN
22	  -- カードIDからユーザーID取得
23	  SELECT u.supabase_auth_user_id INTO v_user_id
24	  FROM attendance.users u WHERE u.card_id = p_card_id;
25	
26	  IF v_user_id IS NULL THEN
27	    RETURN json_build_object('success', false, 'message', '未登録のカードです。', 'user', null, 'type', null);
28	  END IF;
29	
30	  -- メンバー情報取得（display_name + discord_uid）
31	  SELECT m.display_name, m.discord_uid INTO v_display_name, v_discord_uid
32	  FROM member.members m WHERE m.supabase_auth_user_id = v_user_id;
33	
34	  -- display_nameがNULLの場合、auth.usersからglobal_nameをフォールバック
35	  IF v_display_name IS NULL THEN
36	    SELECT au.raw_user_meta_data->'custom_claims'->>'global_name'
37	    INTO v_display_name
38	    FROM auth.users au WHERE au.id = v_user_id;
39	  END IF;
